  const bIdx = finalTodo.findIndex(c => c.id === card2.id);
  const fIdx = finalTodo.findIndex(c => c.id === card6.id);
  const dIdx = finalTodo.findIndex(c => c.id === card4.id);
  assert(
    bIdx < fIdx && fIdx < dIdx,
    'Card F is correctly positioned between Card B and Card D'
  );

  // Cleanup SSE
  sseClient.close();

  // ---- Summary ----
  console.log(`\n=== Results: ${passed} passed, ${failed} failed ===\n`);

  if (failed > 0) {
    process.exit(1);
  }
}

runTests().catch(err => {
  console.error('Test runner error:', err);
  process.exit(1);
});
