 * DELETE /api/cards/:id - Delete a card
 */
router.delete('/:id', async (req, res) => {
  try {
    const db = getDb();
    const { id } = req.params;

    // Verify card exists
    const { rows: existingCards } = await db.query(
      'SELECT id FROM cards WHERE id = $1',
