.header h1 {
  font-size: 20px;
  font-weight: 600;
}

.board {
  display: flex;
  gap: 16px;
  padding: 24px;
  overflow-x: auto;
  min-height: calc(100vh - 53px);
  align-items: flex-start;
}

.column {
  background-color: #ebecf0;
  border-radius: 8px;
  min-width: 280px;
  max-width: 280px;
  padding: 12px;
  display: flex;
  flex-direction: column;
  max-height: calc(100vh - 97px);
}

.column-header {
  font-weight: 600;
  font-size: 15px;
  padding: 4px 8px 12px;
  color: #172b4d;
}

.card-list {
  min-height: 40px;
  flex: 1;
  overflow-y: auto;
  padding-bottom: 8px;
}

.card-list.drag-over {
  background-color: rgba(0, 82, 204, 0.08);
  border-radius: 4px;
}

.card {
  background-color: white;
  border-radius: 4px;
  padding: 8px 12px;
  margin-bottom: 8px;
  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.1);
  cursor: grab;
  font-size: 14px;
  line-height: 1.4;
  word-break: break-word;
  transition: box-shadow 0.15s ease, opacity 0.15s ease;
  user-select: none;
}

.card:hover {
  box-shadow: 0 2px 6px rgba(0, 0, 0, 0.15);
}

.card.dragging {
  opacity: 0.5;
  cursor: grabbing;
}

.card.drag-placeholder {
  background-color: #ebecf0;
  border: 2px dashed #0052cc;
  min-height: 36px;
  border-radius: 4px;
  margin-bottom: 8px;
}

.add-card-form {
  padding-top: 8px;
}

.add-card-input-wrapper {
  position: relative;
}

.add-card-input {
  width: 100%;
  padding: 8px 12px;
  border: 2px solid #0052cc;
  border-radius: 4px;
  font-size: 14px;
  outline: none;
  font-family: inherit;
}

.add-card-input::placeholder {
  color: #6b778c;
}

.add-card-btn {
  width: 100%;
  padding: 8px 12px;
  margin-top: 4px;
  background-color: #0052cc;
  color: white;
  border: none;
  border-radius: 4px;
  font-size: 14px;
  cursor: pointer;
  font-family: inherit;
}

.add-card-btn:hover {
  background-color: #0747a6;
}

.add-card-cancel {
  position: absolute;
  right: 4px;
  top: 50%;
  transform: translateY(-50%);
  background: none;
  border: none;
  font-size: 18px;
  color: #6b778c;
  cursor: pointer;
  padding: 4px;
  line-height: 1;
}

.add-card-cancel:hover {
  color: #172b4d;
}

/* Drop indicator */
.drop-indicator {
  height: 3px;
  background-color: #0052cc;
  border-radius: 2px;
  margin-bottom: 8px;
  transition: opacity 0.1s ease;
}
