}

.add-card-cancel:hover {
  color: #172b4d;
}

/* Drop indicator */
.drop-indicator {
  height: 3px;
  background-color: #0052cc;
  border-radius: 2px;
  margin-bottom: 8px;
  transition: opacity 0.1s ease;
}
