  const PRECISION_THRESHOLD = 1e-10;
  let needsRenormalize = false;
  for (let i = 1; i < cards.length; i++) {
    if (Math.abs(cards[i].position - cards[i - 1].position) < PRECISION_THRESHOLD) {
      needsRenormalize = true;
      break;
    }
