          const match = block.match(/^data: (.+)$/);
          if (match) {
            try {
              events.push(JSON.parse(match[1]));
            } catch (e) {}
          }
        }
      });
    });
    req.on('error', () => resolve(events));

    // Force close after duration
    setTimeout(() => {
      req.destroy();
      resolve(events);
    }, durationMs);
  });
}

