function computePosition(beforePos, afterPos) {
  if (beforePos !== null && afterPos !== null) {
    return (beforePos + afterPos) / 2;
  }
  if (beforePos !== null) {
    return beforePos + 0.5;
  }
  if (afterPos !== null) {
    return afterPos - 0.5;
  }
