  const progressCol = boardAfterMove.find(c => c.id === 'col-progress');

  assert(!todoCol2.cards.find(c => c.id === card1.id), 'Card removed from To Do');
  assert(progressCol.cards.find(c => c.id === card1.id), 'Card exists in In Progress');

